create extension if not exists pgcrypto;
create table tokens(id uuid primary key default gen_random_uuid(),chain_id bigint not null,contract_address text not null check(contract_address=lower(contract_address)),name text not null,symbol text not null,decimals integer not null check(decimals between 0 and 255),total_supply text not null constraint tokens_total_supply_digits check(total_supply ~ '^[0-9]+$'),first_seen_at timestamptz not null default now(),last_updated_at timestamptz not null default now(),created_at timestamptz not null default now(),unique(chain_id,contract_address));
create table token_metrics(id uuid primary key default gen_random_uuid(),token_id uuid not null references tokens on delete cascade,price_usd numeric,market_cap_usd numeric,fully_diluted_value_usd numeric,liquidity_usd numeric,volume_5m_usd numeric,volume_1h_usd numeric,volume_24h_usd numeric,buys_5m integer,sells_5m integer,buys_1h integer,sells_1h integer,buys_24h integer,sells_24h integer,holder_count integer,price_change_5m numeric,price_change_1h numeric,price_change_24h numeric,source text,captured_at timestamptz not null default now());
create index token_metrics_latest on token_metrics(token_id,captured_at desc);
create table token_holders(id uuid primary key default gen_random_uuid(),token_id uuid not null references tokens on delete cascade,wallet_address text not null,balance numeric not null,percentage numeric not null,captured_at timestamptz not null default now());create index token_holders_concentration on token_holders(token_id,percentage desc);
create table token_transactions(id uuid primary key default gen_random_uuid(),token_id uuid not null references tokens on delete cascade,tx_hash text not null,wallet_address text,transaction_type text not null check(transaction_type in ('BUY','SELL','TRANSFER')),event_index integer not null default 0,token_amount numeric,usd_amount numeric,block_number bigint not null,block_timestamp timestamptz not null,created_at timestamptz not null default now(),unique(token_id,tx_hash,event_index));create index token_transactions_latest on token_transactions(token_id,block_timestamp desc);
create table risk_scores(id uuid primary key default gen_random_uuid(),token_id uuid not null references tokens on delete cascade,score integer not null check(score between 0 and 100),risk_level text not null,holder_concentration_score numeric,liquidity_score numeric,contract_score numeric,age_score numeric,activity_score numeric,breakdown jsonb not null default '[]',calculated_at timestamptz not null default now());create index risk_scores_latest on risk_scores(token_id,calculated_at desc);
create table token_rankings(id uuid primary key default gen_random_uuid(),token_id uuid not null references tokens on delete cascade,ranking_type text not null check(ranking_type in ('trending','new','volume')),score numeric not null,rank integer,calculated_at timestamptz not null default now());create index token_rankings_lookup on token_rankings(ranking_type,score desc,calculated_at desc);
alter table tokens enable row level security;alter table token_metrics enable row level security;alter table token_holders enable row level security;alter table token_transactions enable row level security;alter table risk_scores enable row level security;alter table token_rankings enable row level security;
revoke all on tokens,token_metrics,token_holders,token_transactions,risk_scores,token_rankings from anon,authenticated;
grant select on tokens,token_metrics,token_holders,token_transactions,risk_scores,token_rankings to anon,authenticated;
grant all on tokens,token_metrics,token_holders,token_transactions,risk_scores,token_rankings to service_role;
create policy "public read tokens" on tokens for select to anon,authenticated using(true);create policy "public read metrics" on token_metrics for select to anon,authenticated using(true);create policy "public read holders" on token_holders for select to anon,authenticated using(true);create policy "public read transactions" on token_transactions for select to anon,authenticated using(true);create policy "public read risks" on risk_scores for select to anon,authenticated using(true);create policy "public read rankings" on token_rankings for select to anon,authenticated using(true);
